import numpy as npimport pandas as pdimport matplotlib.pyplot as pltfrom matplotlib.gridspec import GridSpecplt.rcParams.update({'lines.linewidth': 0.5})plt.rcParams.update({'font.size': 7})plt.rcParams.update({'font.sans-serif': 'Arial'})plt.rcParams.update({'axes.linewidth': 0.5})plt.rcParams.update({'axes.titlepad': 3})plt.rcParams.update({'axes.titlesize': 8})plt.rcParams.update({'axes.labelpad': 2})plt.rcParams.update({'xtick.major.pad': 2})plt.rcParams.update({'ytick.major.pad': 2})plt.rcParams.update({'xtick.major.width': 0.5})plt.rcParams.update({'ytick.major.width': 0.5})plt.rcParams.update({'xtick.major.size': 1.5})plt.rcParams.update({'ytick.major.size': 1.5})plt.rcParams['legend.fontsize'] = 7path = '/Users/wyan0065/Desktop/OGGM/disequilibrium/pygem_oggm/'mass_var = 'mass_remaining'stats_var = 'disequilibrium_median'# %% add data for Figure_S13Amass_missing_a = pd.read_csv(    path + 'PyGEM_glacier_mass_MT_19_missing_obs_median_a.csv')mass_missing_k = pd.read_csv(    path + 'PyGEM_glacier_mass_MT_19_missing_obs_median_k.csv')mass_with_obs = pd.read_csv(    path + 'PyGEM_glacier_mass_MT_19_with_obs.csv')# %% add lowess fit data for Figure_S13Amass_missing_a_lowess = pd.read_csv(    path + 'PyGEM_glacier_mass_MT_19_missing_obs_mass_remaining_median_a_lowess_fit.csv')mass_missing_k_lowess = pd.read_csv(    path + 'PyGEM_glacier_mass_MT_19_missing_obs_mass_remaining_median_k_lowess_fit.csv')mass_with_obs_lowess = pd.read_csv(    path + 'PyGEM_glacier_mass_MT_19_with_obs_mass_remaining_lowess_fit.csv')# %% add data for Figure_S13Bstats_missing_a = pd.read_csv(    path + 'PyGEM_glacier_stats_MT_19_missing_obs_median_a.csv')stats_missing_k = pd.read_csv(    path + 'PyGEM_glacier_stats_MT_19_missing_obs_median_k.csv')stats_with_obs = pd.read_csv(    path + 'PyGEM_glacier_stats_MT_19_with_obs.csv')# %% add lowess fit data for Figure_S13Bstats_missing_a_lowess = pd.read_csv(    path + 'PyGEM_glacier_stats_MT_19_missing_obs_disequilibrium_median_median_a_lowess_fit.csv')stats_missing_k_lowess = pd.read_csv(    path + 'PyGEM_glacier_stats_MT_19_missing_obs_disequilibrium_median_median_k_lowess_fit.csv')stats_with_obs_lowess = pd.read_csv(    path + 'PyGEM_glacier_stats_MT_19_with_obs_disequilibrium_median_lowess_fit.csv')# %% add plotting settingscolors = {    'median_a': '#489FE3',    'median_k': '#C93735',    'with_obs': '0.55',}median_col = '0.5'q17_col = '0.17'q83_col = '0.83'# %% Create plotfig = plt.figure(figsize=(5.7, 2.26))gs = GridSpec(1, 2, figure=fig,left=0.07, right=0.99, bottom=0.125, top=0.96, wspace=0.15, width_ratios=[1, 1])ax_a = fig.add_subplot(gs[0, 0])ax_b = fig.add_subplot(gs[0, 1])for ax in [ax_a, ax_b]:    ax.set_xlim(-0.1, 6.85)############################################################################ Figure_S13Amass_missing_a_era5 = mass_missing_a[mass_missing_a['gcm'].astype(str).str.lower() == 'era5']mass_missing_a_gcm = mass_missing_a[mass_missing_a['gcm'].astype(str).str.lower() != 'era5']mass_missing_k_era5 = mass_missing_k[mass_missing_k['gcm'].astype(str).str.lower() == 'era5']mass_missing_k_gcm = mass_missing_k[mass_missing_k['gcm'].astype(str).str.lower() != 'era5']mass_with_obs_era5 = mass_with_obs[mass_with_obs['gcm'].astype(str).str.lower() == 'era5']mass_with_obs_gcm = mass_with_obs[mass_with_obs['gcm'].astype(str).str.lower() != 'era5']ax_a.scatter(    mass_missing_a_gcm['temp_ch_ipcc'].values,    mass_missing_a_gcm[mass_var].values,    s=8,    color=colors['median_a'],    alpha=0.42,    linewidths=0,    zorder=5)ax_a.scatter(    mass_missing_a_era5['temp_ch_ipcc'].values,    mass_missing_a_era5[mass_var].values,    marker='*',    s=38,    color=colors['median_a'],    edgecolor='black',    linewidths=0.35,    alpha=0.95,    zorder=30)ax_a.plot(    mass_missing_a_lowess['temp_ch_ipcc'].values,    mass_missing_a_lowess[median_col].values,    color=colors['median_a'],    linewidth=1,    zorder=10)ax_a.fill_between(    mass_missing_a_lowess['temp_ch_ipcc'].values,    mass_missing_a_lowess[q17_col].values,    mass_missing_a_lowess[q83_col].values,    color=colors['median_a'],    alpha=0.15,    linewidth=0,    zorder=1)ax_a.scatter(    mass_missing_k_gcm['temp_ch_ipcc'].values,    mass_missing_k_gcm[mass_var].values,    s=8,    color=colors['median_k'],    alpha=0.42,    linewidths=0,    zorder=5)ax_a.scatter(    mass_missing_k_era5['temp_ch_ipcc'].values,    mass_missing_k_era5[mass_var].values,    marker='*',    s=38,    color=colors['median_k'],    edgecolor='black',    linewidths=0.35,    alpha=0.95,    zorder=30)ax_a.plot(    mass_missing_k_lowess['temp_ch_ipcc'].values,    mass_missing_k_lowess[median_col].values,    color=colors['median_k'],    linewidth=1,    zorder=10)ax_a.fill_between(    mass_missing_k_lowess['temp_ch_ipcc'].values,    mass_missing_k_lowess[q17_col].values,    mass_missing_k_lowess[q83_col].values,    color=colors['median_k'],    alpha=0.15,    linewidth=0,    zorder=1)ax_a.scatter(    mass_with_obs_gcm['temp_ch_ipcc'].values,    mass_with_obs_gcm[mass_var].values,    s=8,    color=colors['with_obs'],    alpha=0.42,    linewidths=0,    zorder=5)ax_a.scatter(    mass_with_obs_era5['temp_ch_ipcc'].values,    mass_with_obs_era5[mass_var].values,    marker='*',    s=38,    color=colors['with_obs'],    edgecolor='black',    linewidths=0.35,    alpha=0.95,    zorder=30)ax_a.plot(    mass_with_obs_lowess['temp_ch_ipcc'].values,    mass_with_obs_lowess[median_col].values,    color=colors['with_obs'],    linewidth=1,    zorder=10)ax_a.fill_between(    mass_with_obs_lowess['temp_ch_ipcc'].values,    mass_with_obs_lowess[q17_col].values,    mass_with_obs_lowess[q83_col].values,    color=colors['with_obs'],    alpha=0.15,    linewidth=0,    zorder=1)ax_a.set_ylim(0, 150)ax_a.set_yticks([0, 50, 100, 150])ax_a.set_xlabel('ΔT (°C)', fontsize=8)ax_a.set_ylabel('Steady-state glacier mass (% rel. to 2020)', fontsize=8)ax_a.text(0.01, 0.93, 'A', transform=ax_a.transAxes,          fontsize=9, fontweight='bold', ha='left', va='bottom')############################################################################ Figure_S13Bstats_missing_a_era5 = stats_missing_a[stats_missing_a['gcm'].astype(str).str.lower() == 'era5']stats_missing_a_gcm = stats_missing_a[stats_missing_a['gcm'].astype(str).str.lower() != 'era5']stats_missing_k_era5 = stats_missing_k[stats_missing_k['gcm'].astype(str).str.lower() == 'era5']stats_missing_k_gcm = stats_missing_k[stats_missing_k['gcm'].astype(str).str.lower() != 'era5']stats_with_obs_era5 = stats_with_obs[stats_with_obs['gcm'].astype(str).str.lower() == 'era5']stats_with_obs_gcm = stats_with_obs[stats_with_obs['gcm'].astype(str).str.lower() != 'era5']ax_b.scatter(    stats_missing_a_gcm['temp_ch_ipcc'].values,    stats_missing_a_gcm[stats_var].values,    s=8,    color=colors['median_a'],    alpha=0.42,    linewidths=0,    zorder=5)ax_b.scatter(    stats_missing_a_era5['temp_ch_ipcc'].values,    stats_missing_a_era5[stats_var].values,    marker='*',    s=38,    color=colors['median_a'],    edgecolor='black',    linewidths=0.35,    alpha=0.95,    zorder=30)ax_b.plot(    stats_missing_a_lowess['temp_ch_ipcc'].values,    stats_missing_a_lowess[median_col].values,    color=colors['median_a'],    linewidth=1,    zorder=10)ax_b.fill_between(    stats_missing_a_lowess['temp_ch_ipcc'].values,    stats_missing_a_lowess[q17_col].values,    stats_missing_a_lowess[q83_col].values,    color=colors['median_a'],    alpha=0.15,    linewidth=0,    zorder=1)ax_b.scatter(    stats_missing_k_gcm['temp_ch_ipcc'].values,    stats_missing_k_gcm[stats_var].values,    s=8,    color=colors['median_k'],    alpha=0.42,    linewidths=0,    zorder=5)ax_b.scatter(    stats_missing_k_era5['temp_ch_ipcc'].values,    stats_missing_k_era5[stats_var].values,    marker='*',    s=38,    color=colors['median_k'],    edgecolor='black',    linewidths=0.35,    alpha=0.95,    zorder=30)ax_b.plot(    stats_missing_k_lowess['temp_ch_ipcc'].values,    stats_missing_k_lowess[median_col].values,    color=colors['median_k'],    linewidth=1,    zorder=10)ax_b.fill_between(    stats_missing_k_lowess['temp_ch_ipcc'].values,    stats_missing_k_lowess[q17_col].values,    stats_missing_k_lowess[q83_col].values,    color=colors['median_k'],    alpha=0.15,    linewidth=0,    zorder=1)ax_b.scatter(    stats_with_obs_gcm['temp_ch_ipcc'].values,    stats_with_obs_gcm[stats_var].values,    s=8,    color=colors['with_obs'],    alpha=0.42,    linewidths=0,    zorder=5)ax_b.scatter(    stats_with_obs_era5['temp_ch_ipcc'].values,    stats_with_obs_era5[stats_var].values,    marker='*',    s=38,    color=colors['with_obs'],    edgecolor='black',    linewidths=0.35,    alpha=0.95,    zorder=30)ax_b.plot(    stats_with_obs_lowess['temp_ch_ipcc'].values,    stats_with_obs_lowess[median_col].values,    color=colors['with_obs'],    linewidth=1,    zorder=10)ax_b.fill_between(    stats_with_obs_lowess['temp_ch_ipcc'].values,    stats_with_obs_lowess[q17_col].values,    stats_with_obs_lowess[q83_col].values,    color=colors['with_obs'],    alpha=0.15,    linewidth=0,    zorder=1)ax_b.set_ylim(0, 1.6)ax_b.set_yticks(np.arange(0, 1.6, 0.3))ax_b.set_xlabel('ΔT (°C)', fontsize=8)ax_b.set_ylabel(r'Median $\alpha$', fontsize=8)ax_b.text(0.01, 0.93, 'B', transform=ax_b.transAxes,          fontsize=9, fontweight='bold', ha='left', va='bottom')################################################################################ Legendax_a.text(3.55, 144, 'Marine-terminating glaciers missing \nfrontal-ablation observations:', fontsize=7,          fontweight='bold', ha='center', va='top')ax_a.text(3.55, 118, r'use median $\alpha$', color=colors['median_a'],          fontsize=7, ha='center', va='top')ax_a.text(3.55, 126, r'use median $k$', color=colors['median_k'],          fontsize=7, ha='center', va='top')ax_a.text(3.55, 110, 'Marine-terminating glaciers with\nfrontal-ablation observations', color=colors['with_obs'],          fontsize=7, ha='center', va='top')ax_b.scatter(    [4.0], [1.15],    marker='o',    s=8,    color='black',    alpha=0.42,    linewidths=0,    zorder=100)ax_b.text(4.3, 1.15, 'based on GCMs', fontsize=7, ha='left', va='center')ax_b.scatter(    [4.0], [1.03],    marker='*',    s=38,    color='white',    edgecolor='black',    linewidths=0.35,    zorder=100)ax_b.text(4.3, 1.03, 'based on ERA5', fontsize=7, ha='left', va='center')ax_b.fill_between(    [3.8, 4.2], [0.80, 0.80], [0.90, 0.90],    color='black',    alpha=0.15,    linewidth=0)ax_b.plot(    [3.8, 4.2], [0.85, 0.85],    color='black',    linewidth=1,    zorder=100)ax_b.text(4.4, 0.85, 'LOWESS fit\n50% [17% to 83%]',          fontsize=7, ha='left', va='center')out_png = '/Users/wyan0065/Desktop/OGGM/disequilibrium/figures/figure_S15.png'plt.savefig(out_png, dpi=600)plt.show()